//! Inert candidate metadata follows actual attributes and tree ownership.
use super::*;
fn start(source:&str)->(Document,Forms,Page){let mut d=crate::html::parse("<body><input id=neighbor value=Seed></body>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://inert-eligibility.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);let out=p.start(&mut d,&mut f,&[Script{node:0,label:"Inert candidate metadata".into(),source:source.into()}]);assert_eq!(out.errors,0,"{}",p.report());(d,f,p)}
#[test]
fn inert_control_eligibility_all_interfaces_use_actual_attributes(){
 start("var doc=document.implementation.createHTMLDocument('inert'),tags=['input','button','select','textarea'],classes=[HTMLInputElement,HTMLButtonElement,HTMLSelectElement,HTMLTextAreaElement];for(var i=0;i<tags.length;i++){var x=doc.createElement(tags[i]),get=Object.getOwnPropertyDescriptor(classes[i].prototype,'willValidate').get;if(x.willValidate!==true||get.call(x)!==true||x.isConnected)throw 'inert candidate '+tags[i];x.disabled=true;if(x.willValidate!==false)throw 'disabled';x.disabled=false;if(x.willValidate!==true)throw 'enabled';}var a=doc.createElement('input');a.readOnly=true;if(a.willValidate)throw 'readonly';a.setAttribute('type','checkbox');if(!a.willValidate)throw 'checkbox readonly';a.setAttribute('type','hidden');if(a.willValidate)throw 'hidden';var b=doc.createElement('button');b.setAttribute('commandfor','target');if(b.willValidate)throw 'Auto command';b.type='submit';if(!b.willValidate)throw 'explicit submit';");
}
#[test]
fn inert_control_eligibility_first_legend_and_datalist_move_with_nodes(){
 start("var doc=document.implementation.createHTMLDocument('inert'),f=doc.createElement('fieldset'),first=doc.createElement('legend'),second=doc.createElement('legend'),x=doc.createElement('input'),wrap=doc.createElement('div'),list=doc.createElement('datalist');f.disabled=true;f.appendChild(first);f.appendChild(second);first.appendChild(wrap);wrap.appendChild(x);if(!x.willValidate)throw 'first legend';second.appendChild(x);if(x.willValidate)throw 'second legend';first.appendChild(x);var outer=doc.createElement('fieldset');outer.disabled=true;outer.appendChild(f);if(x.willValidate)throw 'outer disabled';outer.disabled=false;if(!x.willValidate)throw 'outer enabled';list.appendChild(x);if(x.willValidate)throw 'datalist';doc.body.appendChild(x);if(!x.willValidate)throw 'moved candidate';var select=doc.createElement('select'),b=doc.createElement('button');select.appendChild(b);if(b.willValidate)throw 'Auto select';b.type='submit';if(!b.willValidate)throw 'explicit select';");
}
#[test]
fn inert_control_eligibility_clone_adoption_and_namespace_attributes_keep_identity(){
 start("var doc=new Document(),html='http://www.w3.org/1999/xhtml',x=doc.createElementNS(html,'x:input'),getter=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'willValidate').get;x.setAttributeNS('urn:foreign','p:disabled','');x.setAttributeNS(null,'DISABLED','');if(!getter.call(x))throw 'foreign attributes';x.setAttributeNS(null,'readonly','');if(x.willValidate)throw 'exact readonly';var copy=x.cloneNode(false);if(copy.willValidate||copy===x)throw 'cloned state';x.removeAttributeNS(null,'readonly');if(!x.willValidate||copy.willValidate)throw 'independent sources';var target=document.implementation.createHTMLDocument('target');if(target.adoptNode(copy)!==copy||copy.ownerDocument!==target||getter.call(copy)!==false)throw 'adopted candidate';copy.removeAttribute('readonly');if(!copy.willValidate)throw 'adopted mutation';var fake=doc.createElementNS('urn:foreign','input'),denied=false;try{getter.call(fake);}catch(e){denied=e instanceof TypeError;}if(!denied)throw 'foreign interface';");
}
#[test]
fn inert_control_eligibility_namespace_ancestors_and_reordered_first_legend(){
 start("var doc=new Document(),html='http://www.w3.org/1999/xhtml',x=doc.createElementNS(html,'input'),f=doc.createElementNS(html,'fieldset'),foreign=doc.createElementNS('urn:foreign','fieldset'),fakeLegend=doc.createElementNS('urn:foreign','legend'),first=doc.createElementNS(html,'legend'),second=doc.createElementNS(html,'legend');foreign.setAttribute('disabled','');foreign.appendChild(x);if(!x.willValidate)throw 'foreign fieldset';f.disabled=true;f.appendChild(fakeLegend);fakeLegend.appendChild(x);if(x.willValidate)throw 'foreign legend';f.appendChild(first);f.appendChild(second);first.appendChild(x);if(!x.willValidate)throw 'first HTML legend';f.insertBefore(second,first);if(x.willValidate)throw 'reordered first legend';second.appendChild(x);if(!x.willValidate)throw 'new first legend';var fakeList=doc.createElementNS('urn:foreign','datalist');fakeList.appendChild(x);if(!x.willValidate)throw 'foreign datalist';f.appendChild(x);f.removeAttribute('disabled');f.setAttributeNS('urn:foreign','p:disabled','');if(!x.willValidate)throw 'foreign disabled';");
}
#[test]
fn inert_control_eligibility_parsed_sources_and_readonly_type_matrix(){
 start("var parsed=new DOMParser().parseFromString('<form><fieldset disabled><legend><input id=free></legend><textarea id=blocked></textarea></fieldset><datalist><select id=listed></select></datalist><button id=button type=reset></button></form>','text/html');if(!parsed.getElementById('free').willValidate||parsed.getElementById('blocked').willValidate||parsed.getElementById('listed').willValidate||parsed.getElementById('button').willValidate)throw 'parsed source';var states=['text','search','tel','url','email','password','number','range','color','date','datetime-local','month','week','time','file','checkbox','radio','submit','image','reset','button','hidden','invalid'],doc=document.implementation.createHTMLDocument('matrix'),x=doc.createElement('input');for(var type of states){x.setAttribute('type',type);x.readOnly=false;var barred=type==='hidden'||type==='reset'||type==='button';if(x.willValidate!==!barred)throw 'plain '+type;x.readOnly=true;var readonly=!(type==='checkbox'||type==='radio'||type==='file'||type==='range'||type==='color'||type==='image'||type==='submit');if(x.willValidate!==(!barred&&!readonly))throw 'readonly '+type;}");
}
#[test]
fn inert_control_eligibility_shadowing_is_observable_without_author_callbacks(){
 start("var doc=document.implementation.createHTMLDocument('silent'),x=doc.createElement('input'),P=HTMLInputElement.prototype,d=Object.getOwnPropertyDescriptor(P,'willValidate'),watch=new MutationObserver(function(){throw 'getter mutation callback';});watch.observe(doc,{subtree:true,attributes:true,childList:true});Object.defineProperty(x,'disabled',{get:function(){throw 'author disabled';},configurable:true});Object.defineProperty(x,'willValidate',{value:'own',configurable:true});if(x.willValidate!=='own'||!d.get.call(x))throw 'own shadow';delete x.willValidate;Object.defineProperty(P,'willValidate',{value:'prototype',configurable:true});if(x.willValidate!=='prototype'||!d.get.call(x))throw 'prototype shadow';delete P.willValidate;if(x.willValidate!==undefined||!d.get.call(x))throw 'deleted canonical';Object.defineProperty(P,'willValidate',d);if(!x.willValidate||watch.takeRecords().length)throw 'silent getter';");
}
#[test]
fn inert_control_eligibility_work_deadline_refusal_allocation_free_read_and_recovery(){
 for mode in 0..4{
  let(mut d,mut f,mut p)=start("var doc=document.implementation.createHTMLDocument('budget'),f=doc.createElement('fieldset'),l=doc.createElement('legend'),x=doc.createElement('input');f.disabled=true;f.appendChild(l);l.appendChild(x);var watch=new MutationObserver(function(){});watch.observe(f,{attributes:true,childList:true,subtree:true});");
  let Value::Host(object)=p.runtime.execute("x",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("actual inert handle")};
  let before=(format!("{:?}",d.nodes),p.state.retained,p.state.dom_commits);
  let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.host_work=40,2=>{p.state.retained_limit=p.state.retained;p.state.copy_work=0;},_=>p.state.execution_deadline=Some(Instant::now())};
  let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.control_eligibility_get(object);
  if mode==2{assert!(matches!(result,Ok(Value::Bool(true))));}else{assert!(result.is_err(),"mode {mode}");}
  assert_eq!((format!("{:?}",d.nodes),p.state.retained,p.state.dom_commits),before);assert!(p.take_validation_report().is_none());
  p.state.retained_limit=limit;p.begin_job();p.runtime.execute("if(!x.willValidate||watch.takeRecords().length||x.parentNode!==l||!f.disabled)throw 'inert read recovery';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();
 }
}
#[test]
fn inert_control_eligibility_saved_child_getter_enforces_captured_origin(){
 let(mut d,mut f,mut p)=start("var x=document.implementation.createHTMLDocument('authority').createElement('input'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var getter=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLInputElement.prototype,'willValidate').get;if(!getter.call(x))throw 'saved inert getter';");
 p.set_location(&crate::navigation::address("https://foreign-inert.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("getter.call(x)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");p.set_location(&crate::navigation::address("https://inert-eligibility.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();p.runtime.execute("if(!getter.call(x))throw 'authority recovery';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();
}
